const _section_nash = function section_nash(md){return( md`## 🎲 Nash Equilibrium Analysis`)};

const _nash_analysis = function nash_analysis(payoff_matrix){return(
function nash_analysis(payoff_matrix) {
  const m = payoff_matrix;
  // Best response for YOU
  const youAd_vs_Ad   = m["You Ad, They Ad"].you;
  const youNoAd_vs_Ad = m["You No Ad, They Ad"].you;
  const youAd_vs_NoAd   = m["You Ad, They No Ad"].you;
  const youNoAd_vs_NoAd = m["You No Ad, They No Ad"].you;

  const youBR_vs_Ad = youAd_vs_Ad >= youNoAd_vs_Ad ? "Ad" : "No Ad";
  const youBR_vs_NoAd = youAd_vs_NoAd >= youNoAd_vs_NoAd ? "Ad" : "No Ad";

  // Best response for COMPETITOR
  const themAd_vs_Ad   = m["You Ad, They Ad"].them;
  const themNoAd_vs_Ad = m["You Ad, They No Ad"].them;
  const themAd_vs_NoAd   = m["You No Ad, They Ad"].them;
  const themNoAd_vs_NoAd = m["You No Ad, They No Ad"].them;

  const themBR_vs_Ad = themAd_vs_Ad >= themNoAd_vs_Ad ? "Ad" : "No Ad";
  const themBR_vs_NoAd = themAd_vs_NoAd >= themNoAd_vs_NoAd ? "Ad" : "No Ad";

  // Find pure strategy Nash equilibria
  const pureNash = [];
  // (Ad, Ad)
  if (youBR_vs_Ad === "Ad" && themBR_vs_Ad === "Ad") pureNash.push("Both Advertise");
  // (Ad, NoAd)
  if (youBR_vs_NoAd === "Ad" && themBR_vs_Ad === "No Ad") pureNash.push("You Advertise, Competitor Doesn't");
  // (NoAd, Ad)
  if (youBR_vs_Ad === "No Ad" && themBR_vs_NoAd === "Ad") pureNash.push("You Don't, Competitor Advertises");
  // (NoAd, NoAd)
  if (youBR_vs_NoAd === "No Ad" && themBR_vs_NoAd === "No Ad") pureNash.push("Neither Advertises");

  // Mixed strategy Nash equilibrium
  // Competitor's mixed strategy: probability p they play Ad
  // You are indifferent when: youAd_vs_Ad * p + youAd_vs_NoAd * (1-p) = youNoAd_vs_Ad * p + youNoAd_vs_NoAd * (1-p)
  // p = (youNoAd_vs_NoAd - youAd_vs_NoAd) / (youAd_vs_Ad - youAd_vs_NoAd - youNoAd_vs_Ad + youNoAd_vs_NoAd)
  const denomYou = youAd_vs_Ad - youAd_vs_NoAd - youNoAd_vs_Ad + youNoAd_vs_NoAd;
  const pCompetitorAd = denomYou !== 0
    ? Math.max(0, Math.min(1, (youNoAd_vs_NoAd - youAd_vs_NoAd) / denomYou))
    : null;

  const denomThem = themAd_vs_Ad - themAd_vs_NoAd - themNoAd_vs_Ad + themNoAd_vs_NoAd;
  const pYouAd = denomThem !== 0
    ? Math.max(0, Math.min(1, (themNoAd_vs_NoAd - themAd_vs_NoAd) / denomThem))
    : null;

  // Expected payoff under mixed strategy
  const expectedYou = pYouAd !== null && pCompetitorAd !== null
    ? pYouAd * (pCompetitorAd * youAd_vs_Ad + (1-pCompetitorAd) * youAd_vs_NoAd) +
      (1-pYouAd) * (pCompetitorAd * youNoAd_vs_Ad + (1-pCompetitorAd) * youNoAd_vs_NoAd)
    : null;

  // Dominant strategy check
  const youDominant = (youBR_vs_Ad === youBR_vs_NoAd) ? youBR_vs_Ad : null;
  const themDominant = (themBR_vs_Ad === themBR_vs_NoAd) ? themBR_vs_Ad : null;

  return {
    you: { vsAd: youBR_vs_Ad, vsNoAd: youBR_vs_NoAd, dominant: youDominant },
    them: { vsAd: themBR_vs_Ad, vsNoAd: themBR_vs_NoAd, dominant: themDominant },
    pureNash,
    mixed: { pYouAd, pCompetitorAd, expectedYou },
    gameType: youDominant === "Ad" && themDominant === "Ad" ? "prisoners_dilemma" :
              youDominant === null && themDominant === null ? "no_dominant" :
              "asymmetric"
  };
}(payoff_matrix)
)};

